insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-500','4-25',500,'演出','yǎn chū','buổi diễn','他们正在准备演出。','Tāmen zhèngzài zhǔnbèi yǎnchū.','Họ đang chuẩn bị biểu diễn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-501','4-26',501,'演员','yǎn yuán','diễn viên','他是一名演员。','Tā shì yī míng yǎnyuán.','Anh ấy là một diễn viên.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-502','4-26',502,'阳光','yáng guāng','ánh nắng','今天阳光明媚。','Jīntiān yángguāng míngmèi.','Hôm nay nắng đẹp.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-503','4-26',503,'养成','yǎng chéng','nuôi dưỡng, hình thành','这种习惯需要时间养成。','Zhè zhǒng xíguàn xūyào shíjiān yǎngchéng.','Thói quen này cần thời gian để hình thành.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-504','4-26',504,'样子','yàng zi','kiểu dáng, dáng vẻ','这件衣服的样子很好看。','Zhè jiàn yīfú de yàngzi hěn hǎokàn.','kiểu dáng của quần áo này rất đẹp.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-505','4-26',505,'邀请','yāo qǐng','mời','我们邀请了很多朋友。','Wǒmen yāoqǐng le hěn duō péngyǒu.','Chúng tôi mời rất nhiều bạn bè.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-506','4-26',506,'要是','yào shì','nếu','要是你有时间，我们一起去吧。','Yàoshì nǐ yǒu shíjiān, wǒmen yīqǐ qù ba.','Nếu bạn có thời gian, chúng ta cùng đi nhé.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-507','4-26',507,'钥匙','yào shi','chìa khóa','我找不到我的钥匙了。','Wǒ zhǎo bù dào wǒ de yàoshi le.','Tôi không tìm thấy chìa khóa của mình.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-508','4-26',508,'也许','yě xǔ','có lẽ','也许明天会下雨。','Yěxǔ míngtiān huì xià yǔ.','Có lẽ ngày mai sẽ mưa.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-509','4-26',509,'叶子','yè zi','chiếc lá','树上的叶子变黄了。','Shù shàng de yèzi biàn huáng le.','Lá trên cây đã chuyển sang màu vàng.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-510','4-26',510,'页','yè','trang mạng','请翻到下一页。','Qǐng fān dào xià yī yè.','Vui lòng lật sang trang tiếp theo.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-511','4-26',511,'一切','yī qiè','tất cả','一切都会好的。','Yīqiè dōu huì hǎo de.','Mọi thứ sẽ ổn thôi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-512','4-26',512,'以','yǐ','lấy, với','以他的能力，他能做到。','Yǐ tā de nénglì, tā néng zuò dào.','Với khả năng của anh ấy, anh ấy có thể làm được.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-513','4-26',513,'以为','yǐ wéi','tưởng rằng','我以为他已经走了。','Wǒ yǐwéi tā yǐjīng zǒu le.','Tôi tưởng rằng anh ấy đã đi rồi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-514','4-26',514,'艺术','yì shù','nghệ thuật','他对艺术很有兴趣。','Tā duì yìshù hěn yǒu xìngqù.','Anh ấy rất hứng thú với nghệ thuật.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-515','4-26',515,'意见','yì jiàn','ý kiến','我有一些不同的意见。','Wǒ yǒu yīxiē bùtóng de yìjiàn.','Tôi có một vài ý kiến khác nhau.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-516','4-26',516,'因此','yīn cǐ','cho nên','因此，我们需要改变计划。','Yīncǐ, wǒmen xūyào gǎibiàn jìhuà.','Vì vậy, chúng ta cần thay đổi kế hoạch.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-517','4-26',517,'引起','yǐn qǐ','dẫn đến, gây ra','他的演讲引起了大家的兴趣。','Tā de yǎnjiǎng yǐnqǐ le dàjiā de xìngqù.','Bài diễn thuyết của anh ấy đã thu hút sự quan tâm của mọi người.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-518','4-26',518,'印象','yìn xiàng','ấn tượng','我对他的印象很好。','Wǒ duì tā de yìnxiàng hěn hǎo.','Ấn tượng của tôi về anh ấy rất tốt.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-519','4-26',519,'赢','yíng','thắng','我们赢了比赛。','Wǒmen yíng le bǐsài.','Chúng tôi đã thắng trận đấu.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-520','4-26',520,'应聘','yìng pìn','ứng tuyển','我去公司应聘了。','Wǒ qù gōngsī yìngpìn le.','Tôi đã đến công ty để ứng tuyển.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-521','4-27',521,'永远','yǒng yuǎn','mãi mãi','我们的友谊永远不会改变。','Wǒmen de yǒuyì yǒngyuǎn bù huì gǎibiàn.','Tình bạn của chúng ta sẽ không bao giờ thay đổi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-522','4-27',522,'勇敢','yǒng gǎn','dũng cảm','他很勇敢地面对困难。','Tā hěn yǒnggǎn de miànduì kùnnán.','Anh ấy rất dũng cảm đối mặt với khó khăn.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-523','4-27',523,'优点','yōu diǎn','ưu điểm','他的优点是很认真。','Tā de yōudiǎn shì hěn rènzhēn.','Ưu điểm của anh ấy là rất chăm chỉ.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-524','4-27',524,'优秀','yōu xiù','ưu tú','她是一个优秀的学生。','Tā shì yīgè yōuxiù de xuéshēng.','Cô ấy là một học sinh xuất sắc.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-525','4-27',525,'幽默','yōu mò','hài hước','他讲笑话很幽默。','Tā jiǎng xiàohuà hěn yōumò.','Anh ấy kể chuyện cười rất hài hước.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-526','4-27',526,'尤其','yóu qí','đặc biệt là','我尤其喜欢吃水果。','Wǒ yóuqí xǐhuān chī shuǐguǒ.','Tôi đặc biệt thích ăn trái cây.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-527','4-27',527,'由','yóu','do','由他负责这项工作。','Yóu tā fùzé zhè xiàng gōngzuò.','Công việc này do anh ấy phụ trách.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-528','4-27',528,'由于','yóu yú','do','由于下雨，我们取消了计划。','Yóuyú xiàyǔ, wǒmen qǔxiāo le jìhuà.','Do trời mưa, chúng tôi đã hủy bỏ kế hoạch.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('4-529','4-27',529,'邮局','yóu jú','bưu điện','我去邮局寄信。','Wǒ qù yóujú jì xìn.','Tôi đi bưu điện gửi thư.');